use std::fmt;

type Thunk = Box<dyn Fn() + Send + 'static>;

// the pattern std::io uses: io::Result<T> = Result<T, io::Error>
type Result<T> = std::result::Result<T, fmt::Error>;

fn returns_long_type() -> Thunk {
    Box::new(|| println!("hi"))
}

fn write_twice(s: &str) -> Result<String> {
    let mut out = String::new();
    fmt::write(&mut out, format_args!("{s}{s}"))?;
    Ok(out)
}

fn main() {
    type Kilometers = i32;
    let x: i32 = 5;
    let y: Kilometers = 5;
    println!("x + y = {}", x + y);

    let f: Thunk = returns_long_type();
    f();
    println!("{:?}", write_twice("ab"));
}

