    eprintln!("fatal: {msg}");
    std::process::exit(0)
}

fn main() {
    let inputs = ["3", "x", "4"];
    let mut total = 0;
    for s in inputs {
        let n: u32 = match s.parse() {
            Ok(n) => n,
            Err(_) => continue,
        };
        total += n;
    }
    println!("total {total}");

    let config: Option<&str> = Some("debug");
    let level = match config {
        Some(l) => l,
        None => fail("no config"),
    };
    println!("level {level}");
}

