use std::fmt::Debug;

fn show<T: Debug + ?Sized>(t: &T) {
    println!("{t:?}");
}

fn main() {
    show(&5);
    show("a str is a DST");      // T = str
    show(&[1, 2, 3][..]);         // T = [i32]
}

fn add_one(x: i32) -> i32 {
    x + 1
}

fn do_twice(f: fn(i32) -> i32, arg: i32) -> i32 {
    f(arg) + f(arg)
}

#[derive(Debug)]
enum Status {
    Value(u32),
}

fn main() {
    println!("The answer is: {}", do_twice(add_one, 5));

    let list_of_numbers = vec![1, 2, 3];
    let strings: Vec<String> = list_of_numbers.iter().map(ToString::to_string).collect();
    println!("{strings:?}");

    // a tuple-struct or enum-variant name is a function too
    let statuses: Vec<Status> = (0u32..3).map(Status::Value).collect();
    println!("{statuses:?}");

    let ops: [(&str, fn(i32, i32) -> i32); 2] = [("add", |a, b| a + b), ("max", i32::max)];
    for (name, op) in ops {
        println!("{name}: {}", op(3, 7));
    }
}

fn returns_closure() -> impl Fn(i32) -> i32 {
    |x| x + 1
}

fn returns_initialized_closure(init: i32) -> impl Fn(i32) -> i32 {
    move |x| x + init
}

fn main() {
    let handlers = vec![returns_closure(), returns_initialized_closure(123)];
    for handler in handlers {
        let output = handler(5);
        println!("{output}");
    }
}

fn returns_closure() -> Box<dyn Fn(i32) -> i32> {
    Box::new(|x| x + 1)
}

fn returns_initialized_closure(init: i32) -> Box<dyn Fn(i32) -> i32> {
    Box::new(move |x| x + init)
}

fn make_op(name: &str) -> Box<dyn Fn(i32) -> i32> {
    match name {
        "double" => Box::new(|x| x * 2),
        "square" => Box::new(|x| x * x),
        _ => Box::new(|x| x),
    }
}

fn compose<A, B, C>(f: impl Fn(A) -> B, g: impl Fn(B) -> C) -> impl Fn(A) -> C {
    move |x| g(f(x))
}

fn main() {
    let handlers = vec![returns_closure(), returns_initialized_closure(123)];
    for handler in handlers {
        println!("{}", handler(5));
    }

    let pipeline = compose(make_op("double"), make_op("square"));
    println!("{}", pipeline(3));
}

use std::collections::HashMap;

fn main() {
    let mut ops: HashMap<&str, fn(f64, f64) -> f64> = HashMap::new();
    // ops.insert("+", ...);

    for (a, op, b) in [(2.0, "+", 3.0), (2.0, "pow", 10.0), (9.0, "/", 2.0), (1.0, "%", 2.0)] {
        match ops.get(op) {
            Some(f) => println!("{a} {op} {b} = {}", f(a, b)),
            None => println!("{a} {op} {b}: unknown op"),
        }
    }
}
